"""Standalone report generated from executed aggregates, without customer identifiers."""
import html


def money(x):
    return '£' + f'{x:,.0f}'.replace(',', ' ')


def number(x):
    return f"{x:,}".replace(",", " ")


def percent(x):
    return f"{x*100:.1f}".replace(".", ",") + "%"


def render(s, rows):
    tr = ''.join(f'<tr><th>{html.escape(r["label"])}</th><td>{number(r["customers"])}</td><td>{percent(r["return_rate"])}</td><td>{percent(r["ci_low"])}–{percent(r["ci_high"])}</td><td>{money(r["future_net_gbp"])}</td><td>{money(r["future_net_per_customer_gbp"])}</td></tr>' for r in rows)
    bars = []
    for i, r in enumerate(rows):
        y = 38 + i*62
        bars.append(f'<text x="12" y="{y}" class="chartlabel">{html.escape(r["label"])}</text><line x1="{330+r["ci_low"]*420:.2f}" y1="{y-5}" x2="{330+r["ci_high"]*420:.2f}" y2="{y-5}" stroke="#0d7d73" stroke-width="5"/><circle cx="{330+r["return_rate"]*420:.2f}" cy="{y-5}" r="7" fill="#183d46"/><text x="782" y="{y}" class="chartvalue">{percent(r["return_rate"])}</text>')
    axis = ''.join(f'<line x1="{330+i*105}" x2="{330+i*105}" y1="10" y2="325" stroke="#dbe5e4"/><text x="{330+i*105}" y="350" text-anchor="middle" class="axis">{i*25}%</text>' for i in range(5))
    chart = f'<svg viewBox="0 0 860 370" role="img" aria-label="Доля клиентов с положительной покупкой в октябре–ноябре 2011 и 95% интервалы Wilson">{axis}{"".join(bars)}</svg>'
    share_bars = []
    for i, r in enumerate(rows):
        y = 30 + i*70
        customer_share = r['customers']/s['customers']
        revenue_share = r['future_net_gbp']/s['holdout_existing_net_gbp']
        share_bars.append(f'<text x="12" y="{y}" class="chartlabel">{html.escape(r["label"])}</text><rect x="330" y="{y-14}" width="{customer_share*700:.2f}" height="12" fill="#91c6bb"/><rect x="330" y="{y+3}" width="{revenue_share*700:.2f}" height="12" fill="#183d46"/><text x="780" y="{y-3}" class="axis">{percent(customer_share)}</text><text x="780" y="{y+15}" class="axis">{percent(revenue_share)}</text>')
    share_axis = ''.join(f'<line x1="{330+i*105}" x2="{330+i*105}" y1="4" y2="352" stroke="#dbe5e4"/><text x="{330+i*105}" y="378" text-anchor="middle" class="axis">{i*15}%</text>' for i in range(5))
    share_chart = f'<svg viewBox="0 0 860 398" role="img" aria-label="Доля каждого сегмента в клиентской базе и в обороте базы после отмен">{share_axis}{"".join(share_bars)}</svg>'
    instructions = {
        'loyal_high_value':'Проверить ценность сервиса и персональных рекомендаций. Скидка без теста может субсидировать покупки, которые произошли бы и так.',
        'active_repeat':'Кандидаты для теста рекомендаций и cross-sell. Оценивать дополнительный оборот и стоимость контакта, а не только открытия сообщений.',
        'recent_single':'Проверить сценарий второй покупки. Недавняя единственная покупка означает только одну наблюдаемую покупку в доступной истории.',
        'at_risk_repeat':'Кандидаты для ограниченного пилота возврата. Пауза более 90 дней — правило сегментации, а не доказанный отток.',
        'other_buyers':'Сначала изучить подгруппы: давние разовые покупки и редкие повторные покупки. Единая массовая скидка может оказаться неэффективной.',
    }
    notes = ''.join(f'<article class="action"><h3>{html.escape(r["label"])}</h3><p>{instructions[r["segment"]]}</p><p class="small">{number(r["customers"])} клиентов · повторная покупка {percent(r["return_rate"])} · {money(r["future_net_per_customer_gbp"])} оборота после отмен на клиента</p></article>' for r in rows)
    return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Customer Analytics — сегменты и проверка на будущем периоде</title><meta name="description" content="RFM-сегментация клиентов: SQL, Python, проверка на будущем периоде без утечки данных, рекомендации для CRM."><style>
:root{{--ink:#16343a;--muted:#587074;--line:#d6e2e0;--teal:#0d7d73;--bg:#f4f7f5}}*{{box-sizing:border-box}}body{{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,Segoe UI,sans-serif}}header,main,footer{{max-width:1220px;margin:auto;padding:24px 36px}}header{{border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;font-size:12px;letter-spacing:1.3px}}header a{{color:var(--ink)}}h1{{font-size:clamp(36px,5vw,68px);line-height:1.06;letter-spacing:-2.5px;max-width:850px;margin:22px 0}}h2{{font-size:30px;line-height:1.2;letter-spacing:-.8px}}h3{{font-size:17px;margin:0 0 9px}}.kicker{{color:var(--teal);font-size:12px;letter-spacing:2px;font-weight:750;text-transform:uppercase}}.intro{{max-width:820px;color:var(--muted);font-size:19px}}.hero{{padding:34px 0 25px}}.periods{{display:grid;grid-template-columns:1.4fr 1fr;gap:2px;margin:34px 0}}.periods div{{padding:19px 24px;background:#dfece8;border-left:5px solid var(--teal)}}.periods div:last-child{{background:#16343a;color:white}}.periods strong,.periods span{{display:block}}.periods span{{font-size:13px}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:28px 0 44px}}.metric{{padding:22px;background:white;border:1px solid var(--line);border-radius:5px}}.metric b{{font-size:32px;letter-spacing:-1px;display:block}}.metric span{{font-size:12px;color:var(--muted)}}section{{margin:48px 0}}.small{{font-size:12px;color:var(--muted)}}.grid{{display:grid;grid-template-columns:1fr 1fr;gap:28px}}.panel{{border:1px solid var(--line);border-radius:7px;background:white;padding:28px}}.panel p{{color:var(--muted);font-size:14px}}.callout{{border-left:4px solid #d49b45;background:#fff6e8;padding:17px 22px;color:#705221;font-size:14px}}.chart{{background:white;border:1px solid var(--line);padding:25px;border-radius:7px}}svg{{display:block;width:100%;height:auto}}.chartlabel{{font:14px system-ui;fill:#16343a}}.chartvalue{{font:600 16px system-ui;fill:#16343a}}.axis{{font:12px system-ui;fill:#587074}}.scroll{{overflow-x:auto}}table{{border-collapse:collapse;width:100%;font-size:13px;background:white;min-width:850px}}th,td{{padding:16px 13px;text-align:right;border-bottom:1px solid var(--line)}}th:first-child{{text-align:left;max-width:250px}}thead th{{background:#16343a;color:white;font-weight:600}}.actions{{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}}.action{{padding:23px;background:white;border:1px solid var(--line);border-radius:6px}}.action p{{font-size:14px;color:var(--muted)}}.action:last-child{{grid-column:1/-1}}.buttons{{display:flex;flex-wrap:wrap;gap:10px}}.button{{text-decoration:none;padding:10px 17px;border-radius:4px;background:var(--teal);color:white;font-size:13px;font-weight:650}}.secondary{{background:white;border:1px solid var(--line);color:var(--ink)}}li{{margin:10px 0}}code{{background:#e6eeeb;padding:2px 5px}}details{{padding:14px 0;border-bottom:1px solid var(--line)}}summary{{cursor:pointer;font-weight:650}}footer{{border-top:1px solid var(--line);font-size:12px;color:var(--muted)}}a{{color:#086c65}}a:focus-visible,summary:focus-visible{{outline:3px solid #d49b45;outline-offset:4px}}@media(max-width:750px){{header,main,footer{{padding:20px}}h1{{letter-spacing:-1.5px}}.metrics,.grid,.actions{{grid-template-columns:1fr 1fr}}.periods{{grid-template-columns:1fr}}.metric{{padding:16px}}.metric b{{font-size:26px}}.grid{{grid-template-columns:1fr}}.chart{{padding:12px;overflow:auto}}.chart svg{{min-width:700px}}.actions{{grid-template-columns:1fr}}}}
</style></head><body><header><span>РАФИФ АЛШАУИ / CUSTOMER ANALYTICS</span><span>SQL · PYTHON · CRM</span></header><main>
<div class="hero"><div class="kicker">03 / Отчёт по клиентской базе</div><h1>Какие клиенты формируют<br>будущие продажи?</h1><p class="intro">Пять прозрачных сегментов RFM, проверенных на следующем периоде. От исходных операций до рекомендаций для CRM и плана измерения эффекта.</p><p class="small">Открытые данные UCI Online Retail · 541 909 строк · анализ исторических покупок 2010–2011</p></div>
<div class="periods"><div><strong>Признаки: 01.12.2010 — 30.09.2011</strong><span>Сегменты зафиксированы на 1 октября. В расчёт RFM будущие покупки не попадают.</span></div><div><strong>Проверка: 01.10 — 30.11.2011</strong><span>61 день наблюдения после среза. Неполный декабрь исключён.</span></div></div>
<div class="metrics"><div class="metric"><b>{number(s['customers'])}</b><span>идентифицированных покупателей до среза</span></div><div class="metric"><b>{percent(s['return_rate'])}</b><span>совершили покупку в будущем периоде</span></div><div class="metric"><b>{money(s['holdout_existing_net_gbp'])}</b><span>оборот после отмен этой базы в holdout</span></div><div class="metric"><b>{s['checks_passed']}</b><span>пройденных проверок данных и расчётов</span></div></div>
<section><div class="kicker">01 / Что проверяем</div><h2>Сегментация полезна, если помогает принять решение</h2><div class="grid"><div class="panel"><h3>Бизнес-вопрос</h3><p>Отличается ли последующая покупательская активность у клиентов с разной давностью, частотой и суммой покупок? Какие группы стоит включить в CRM-пилоты и как оценивать их результат?</p><h3>Единица анализа</h3><p>Один CustomerID с хотя бы одной положительной покупкой до 1 октября 2011. Все эти клиенты остаются в знаменателе, даже если в октябре–ноябре они ничего не купили.</p></div><div class="panel"><h3>Исполнение</h3><p>Python: очистка источника и независимые контрольные расчёты. SQLite: CTE, агрегации, LEFT JOIN, срез признаков и присоединение будущих результатов. Итоги выгружаются в CSV/JSON; персональные строки клиентов не публикуются.</p><h3>Контроль утечки</h3><p>Удаление всех строк будущего периода не меняет RFM и присвоенные сегменты. Проверяется автоматически при каждом запуске.</p></div></div></section>
<section><div class="kicker">02 / Результат проверки</div><h2>Повторная покупка за следующие 61 день</h2><p class="small">Точка — доля покупателей. Отрезок — 95% интервал Wilson. Интервалы описывают неопределённость доли при биномиальной модели; различия не доказывают влияние коммуникации.</p><div class="chart">{chart}</div><div class="scroll"><table><thead><tr><th>Сегмент</th><th>Клиенты</th><th>Повторная покупка</th><th>95% ДИ</th><th>Оборот после отмен</th><th>На клиента</th></tr></thead><tbody>{tr}</tbody></table></div></section>
<section><h2>Численность и денежный вклад — разные приоритеты</h2><p class="small">Светлая полоса — доля сегмента в базе. Тёмная — доля в обороте этой базы после отмен за holdout. Обе доли рассчитаны от одной фиксированной клиентской базы.</p><div class="chart">{share_chart}</div><p class="callout">Ценные регулярные составляют {percent(rows[0]['share'])} базы и приносят {percent(rows[0]['future_net_gbp']/s['holdout_existing_net_gbp'])} её оборота после отмен в будущем периоде. Это аргумент для проверки качества сервиса и удержания; автоматически назначать им скидки из этого наблюдения не следует.</p></section>
<section><div class="kicker">03 / Правила сегментации</div><h2>Объяснимые правила вместо непрозрачного рейтинга</h2><div class="panel"><p>R — число календарных дней с последней положительной покупки до среза. F — число уникальных положительных InvoiceNo за историю. M — сумма принятых строк истории с учётом отмен. Правила применяются сверху вниз; каждый клиент входит ровно в один сегмент.</p><ol><li><strong>Ценные регулярные:</strong> R ≤ 30 дней, F ≥ 5 и M ≥ £1 000.</li><li><strong>Повторные с паузой:</strong> R > 90 дней и F ≥ 3.</li><li><strong>Недавняя единственная покупка:</strong> R ≤ 30 дней и F = 1.</li><li><strong>Активные повторные:</strong> R ≤ 60 дней и F ≥ 2, если не попали в первый сегмент.</li><li><strong>Остальные:</strong> все оставшиеся покупатели.</li></ol><p>Пороги фиксированы и не оптимизировались по результатам holdout. Это рабочие гипотезы для пилота, а не доказанно оптимальная сегментация.</p></div></section>
<section><div class="kicker">04 / Решение для бизнеса</div><h2>Следующий шаг — разные пилоты для разных сегментов</h2><div class="actions">{notes}</div><p class="callout">Наблюдаемая связь между сегментом и будущей покупкой не является эффектом CRM. В источнике нет назначений коммуникаций, затрат на маркетинг и маржи. ROI, прирост продаж от кампании и «сэкономленные деньги» здесь не рассчитываются.</p><div class="panel"><h3>Как проверить пользу рекомендаций</h3><p>Случайно разделить клиентов внутри выбранного сегмента на тест и контроль до начала контактов. Зафиксировать цель, длительность и минимально значимый эффект; оценивать дополнительный оборот после отмен на назначенного клиента, стоимость коммуникации и отписки. При наличии себестоимости перейти к дополнительной марже. Не менять правила сегментации задним числом по итогам теста.</p></div></section>
<section><div class="kicker">05 / Покрытие и ограничения</div><h2>Где заканчиваются выводы</h2><div class="grid"><div class="panel"><h3>Мост сверки оборота holdout</h3><p>База сегментации: <strong>{money(s['holdout_existing_net_gbp'])}</strong><br>Прочие известные ID: <strong>{money(s['holdout_other_known_net_gbp'])}</strong><br>Операции без CustomerID: <strong>{money(s['holdout_unknown_net_gbp'])}</strong><br>Весь holdout: <strong>{money(s['holdout_all_net_gbp'])}</strong></p><p>Прочие известные ID могут быть новыми наблюдаемыми покупателями или клиентами только с отменами в истории. Их нельзя автоматически назвать новыми клиентами компании.</p></div><div class="panel"><h3>Качество данных</h3><p>{number(s['excluded_rows'])} строк исключены по правилам даты, цены и знака операции. {number(s['exact_duplicate_rows_retained'])} точных повторов сохранены: уникального идентификатора строки нет.</p><p>При удалении повторов сегмент меняется у {s['dedup_sensitivity']['customers_with_changed_segment']} клиентов; оборот после отмен существующей базы отличается на {money(s['dedup_sensitivity']['existing_holdout_net_delta_gbp'])}. Доля положительных продаж holdout без CustomerID: {percent(s['holdout_missing_id_positive_sales_share'])}.</p></div></div><details><summary>Отмены, деньги и история</summary><p>Положительная продажа: Quantity &gt; 0, UnitPrice &gt; 0 и InvoiceNo без префикса C. Отмена: Quantity &lt; 0, UnitPrice &gt; 0 и префикс C. Сумма строки округляется до пенса методом half-to-even. Отмены относятся к датам их записи и не сопоставляются с конкретными заказами. Денежный итог — оборот после отмен, а не прибыль или бухгалтерская выручка. История начинается в декабре 2010; первая наблюдаемая покупка не обязательно первая в жизни клиента.</p></details><details><summary>Статистические ограничения</summary><p>Это один исторический магазин и сезонный период перед Рождеством. Сегменты отражают накопленную историю, разные сроки жизни клиентов и интенсивность покупок. Сравнение не рандомизировано, поэтому нельзя трактовать его причинно или переносить коэффициенты на другой бизнес без повторной проверки. Персональные данные и события контактов в проекте отсутствуют.</p></details></section>
<section class="panel"><div class="kicker">Воспроизвести</div><h2>Код, результаты и проверки</h2><p>Python 3.11+ · исходный XLSX сверяется по SHA-256 · расчёты выполняются локально</p><div class="buttons"><a class="button" href="README.md">Методика и запуск</a><a class="button secondary" href="run.py">Python</a><a class="button secondary" href="segmentation.sql">SQL</a><a class="button secondary" href="results/segments.csv">CSV сегментов</a><a class="button secondary" href="results/validation.json">Протокол проверок</a></div><p><code>python run.py --input "../data/Online Retail.xlsx"</code></p><p class="small">Источник: Chen, D. (2015). <a href="https://doi.org/10.24432/C5BW33">UCI Online Retail</a> · <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Результаты этого проекта относятся к открытым данным и не заявляются коммерческими достижениями у работодателя.</p></section>
</main><footer>Customer Analytics · воспроизводимый анализ клиентской базы · октябрь 2026</footer></body></html>'''
